from typing import List, Dict, Any

class ModerationResponse:
    def __init__(self, text: str, categories: Dict[str, float], decision: str, raw_response: Any = None):
        self.text = text
        self.categories = categories
        self.decision = decision
        self.raw_response = raw_response

class BatchModerationRequest:
    def __init__(self, texts: List[str]):
        self.texts = texts

class BatchModerationResponse:
    def __init__(self, results: List[ModerationResponse]):
        self.results = results

class RedactionResponse:
    def __init__(self, original_text: str, redacted_text: str, categories: Dict[str, float], spans: List[Dict[str, Any]]):
        self.original_text = original_text
        self.redacted_text = redacted_text
        self.categories = categories
        self.spans = spans

from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential

def get_content_safety_client(endpoint: str, api_key: str) -> ContentSafetyClient:
    return ContentSafetyClient(endpoint, AzureKeyCredential(api_key))

from typing import List, Dict, Any
from azure.ai.contentsafety.models import AnalyzeTextOptions
from safety_client import get_content_safety_client
from safety_models import BatchModerationRequest, BatchModerationResponse, ModerationResponse

def moderate_batch(batch_request: BatchModerationRequest, config: Dict[str, Any] = None) -> BatchModerationResponse:
    config = config or {}
    client = get_content_safety_client(config['endpoint'], config['api_key'])
    results = []
    for text in batch_request.texts:
        response = client.analyze_text(AnalyzeTextOptions(text=text, output_type='EightSeverityLevels'))
        categories = {category.category: category.severity for category in response.categories_analysis}
        decision = "unsafe" if any(s > 0 for s in categories.values()) else "safe" # Simplified decision logic
        results.append(ModerationResponse(text=text, categories=categories, decision=decision, raw_response=response))
    return BatchModerationResponse(results=results)

from typing import Dict, Any
from safety_models import ModerationResponse

def apply_safety_thresholds(moderation_response: ModerationResponse, thresholds: Dict[str, float]) -> Dict[str, Any]:
    decision = "ALLOW" # Default to allow
    reasons = []

    for category, severity in moderation_response.categories.items():
        # Azure Content Safety returns severity 0-7, normalize to 0-1 for threshold comparison
        normalized_severity = severity / 7.0

        if category in thresholds and normalized_severity > thresholds[category]:
            decision = "DENY"
            reasons.append(f"Category '{category}' exceeded threshold (severity: {normalized_severity:.2f}, threshold: {thresholds[category]:.2f})")

    if not reasons:
        reasons.append("No categories exceeded thresholds.")

    return {
        "text": moderation_response.text,
        "categories_severity": moderation_response.categories,
        "decision": decision,
        "reasons": reasons,
        "provider": "Azure Content Safety (implicit)" # Explicitly refer to the source of categories
    }
